      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "This living network meta-analysis is the fifth version. The previous versions are available in the supplementary material.",
      "reason": "Identifies the review as an update of previous versions, explaining the need for the current review in the context of existing systematic reviews."
    },
