    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "PRESENT",
      "chunk_id": "text_23",
      "quote": "To facilitate interpretation of the results, we calculated absolute effects for outcomes in which the summary measure was an odds ratio or ratio of means.",
      "reason": "The text describes the method used to re-express synthesized relative results (odds ratio/ratio of means) into absolute effects."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "PRESENT",
      "chunk_id": "text_19",
      "quote": "For continuous outcomes, we used the mean difference... because we expected similar durations across randomised trials. For time to symptom resolution, we first performed the analyses using the relative effect measure ratio of means... because we expected substantial variation between studies.",
      "reason": "The text provides the rationale for choosing specific effect measures based on expected variation in the data."
    }
  ],
  "confidence": 95
